// src/App.js
import React from 'react';
import { BrowserRouter as Router, Route, Routes } from 'react-router-dom';
import './assets/css/style.css';
import Header from './layout/header/header';
import Banner from './layout/banner/banner';
import Section from './layout/section/section';
import Expert from './layout/experts/expert';
import Testimonal from './layout/testimonal/testimonial';
import Resorce from './layout/resource/ressouce';
import Footer from './layout/footer/footer';
import NewPage from './pages/NewPage'; // Import the new page component
import CONTACT from './pages/CONTACT'; // Import the new page component
import COMPANY from './pages/COMPANY'; // Import the new page component
import RESOURCE from './pages/RESOURCE'; // Import the new page component
import TESTIMONIAL from './pages/TESTIMONIAL'; // Import the new page component

import logo from './assets/images/logo.png'; // Ensure the correct path

function App() {
  return (
    <Router>
      <div className="App">
        <Header logo={logo} />
        <Routes>
          <Route path="/" element={
            <>
              <Banner />
              <Section />
              <Expert />
              <Testimonal />
              <Resorce />
            </>
          } />
          <Route path="/new-page" element={<NewPage />} />
          <Route path="/contact" element={<CONTACT />} />
          <Route path="/company" element={<COMPANY />} />
          <Route path="/resource" element={<RESOURCE />} />
          <Route path="/testimonial" element={<TESTIMONIAL />} />
          
        </Routes>
        <Footer />
      </div>
    </Router>
  );
}

export default App;
